<section class="admin-panel admin-table-panel"><div class="table-toolbar table-toolbar-stack"><form class="admin-search" method="get" action="<?= e(admin_url('/messages')) ?>"><label class="sr-only" for="message-search">Search enquiries</label><input id="message-search" type="search" name="q" value="<?= e($query) ?>" placeholder="Search name, business or email"><select name="type" aria-label="Filter by enquiry type"><option value="">All enquiry types</option><option value="wholesale" <?= $type === 'wholesale' ? 'selected' : '' ?>>Wholesale</option><option value="contact" <?= $type === 'contact' ? 'selected' : '' ?>>Contact</option></select><button type="submit">Filter ↗</button></form><span class="toolbar-meta">Showing <?= e(count($messages['items'] ?? array())) ?> of <?= e($messages['total'] ?? 0) ?></span></div><?php if (empty($messages['items'])): ?><div class="empty-state table-empty"><span>◌</span><strong>No enquiries found</strong><p>Website contact and wholesale forms will appear here in live MySQL mode.</p></div><?php else: ?><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>From</th><th>Type</th><th>Market</th><th>Received</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody><?php foreach ($messages['items'] as $message): ?><tr><td><div class="table-primary"><a href="<?= e(admin_url('/messages/view/' . (int) $message['id'])) ?>"><?= e($message['name']) ?></a><small><?= e($message['business_name'] ?: $message['email']) ?></small></div></td><td><span class="message-type <?= e($message['message_type']) ?>"><?= e($message['message_type']) ?></span></td><td><?= e($message['country'] ?: '—') ?></td><td><time datetime="<?= e($message['created_at']) ?>"><?= e(date('d M Y / H:i', strtotime($message['created_at']))) ?></time></td><td><div class="table-actions"><a class="icon-action" href="<?= e(admin_url('/messages/view/' . (int) $message['id'])) ?>">Open</a><form method="post" action="<?= e(admin_url('/messages')) ?>" data-confirm="Delete this enquiry?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="admin_action" value="delete_message"><input type="hidden" name="id" value="<?= e($message['id']) ?>"><button class="icon-action danger" type="submit">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php if (($messages['pages'] ?? 1) > 1): ?><nav class="admin-pagination" aria-label="Enquiries pagination"><?php for ($page = 1; $page <= (int) $messages['pages']; $page++): ?><a class="<?= $page === (int) $messages['page'] ? 'is-current' : '' ?>" href="<?= e(admin_url('/messages?' . http_build_query(array_filter(array('q' => $query, 'type' => $type, 'page' => $page))))) ?>"><?= e($page) ?></a><?php endfor; ?></nav><?php endif; ?></section>
